import { PassThrough } from "node:stream";
import { StdioServerTransport } from "@modelcontextprotocol/server/stdio";
import { afterEach, describe, expect, it, vi } from "vitest";
import { createInstrumentedStdioTransport } from "./stdio-observability.js";

vi.mock("./telemetry.js", () => ({
	tracer: {
		startActiveSpan: (...args: unknown[]) => {
			const callback = args.at(-1) as (span: unknown) => unknown;
			return callback({
				setAttribute: () => undefined,
				setStatus: () => undefined,
				addEvent: () => undefined,
				end: () => undefined,
			});
		},
	},
}));
vi.mock("./metrics.js", () => ({ stdioParseErrors: { add: () => undefined } }));

afterEach(() => vi.restoreAllMocks());

describe("bughunt: stdio malformed-line drain cap", () => {
	it("still delivers a valid request that follows 100 malformed lines in the same chunk", async () => {
		vi.spyOn(console, "error").mockImplementation(() => undefined);
		const stdin = new PassThrough();
		const stdout = new PassThrough();
		const transport = createInstrumentedStdioTransport(
			new StdioServerTransport(stdin, stdout),
		);
		const received: unknown[] = [];
		transport.onmessage = (message) => received.push(message);
		await transport.start();

		const malformed = Array.from({ length: 100 }, () => "{bad}").join("\n");
		stdin.write(`${malformed}\n{"jsonrpc":"2.0","id":1,"method":"ping"}\n`);

		// Give the transport several macrotask turns; no further stdin data
		// arrives, exactly like a client waiting for its ping response.
		for (let turn = 0; turn < 5; turn += 1) {
			await new Promise((resolve) => setImmediate(resolve));
		}

		// The unpatched SDK ReadBuffer skips SyntaxError lines and delivers this.
		expect(received).toEqual([{ jsonrpc: "2.0", id: 1, method: "ping" }]);
		await transport.close();
	});

	it("control: the uninstrumented SDK transport delivers the same request", async () => {
		const stdin = new PassThrough();
		const stdout = new PassThrough();
		const transport = new StdioServerTransport(stdin, stdout);
		const received: unknown[] = [];
		transport.onmessage = (message) => received.push(message);
		await transport.start();
		const malformed = Array.from({ length: 100 }, () => "{bad}").join("\n");
		stdin.write(`${malformed}\n{"jsonrpc":"2.0","id":1,"method":"ping"}\n`);
		for (let turn = 0; turn < 5; turn += 1) {
			await new Promise((resolve) => setImmediate(resolve));
		}
		expect(received).toEqual([{ jsonrpc: "2.0", id: 1, method: "ping" }]);
		await transport.close();
	});
});
