describe("bughunt: rejected initialize requests", () => {
	it("closes the per-session MCP server when the SDK rejects initialize before assigning a session id", async () => {
		vi.spyOn(console, "error").mockImplementation(() => undefined);
		let openServers = 0;
		const factory = () => {
			const server = new McpServer({ name: "bughunt", version: "1.0.0" });
			openServers += 1;
			const close = server.close.bind(server);
			let closed = false;
			server.close = async () => {
				if (!closed) {
					closed = true;
					openServers -= 1;
				}
				await close();
			};
			return Promise.resolve(server);
		};
		const handle = await startStreamableHttpServer(
			{ transport: "http", host: "127.0.0.1", port: 0 },
			"fake-key",
			factory,
			{ maxSessions: 2 },
		);
		handles.push(handle);
		const port = serverPort(handle.server);

		// A client that omits text/event-stream from Accept gets a 406 from the
		// SDK before onsessioninitialized fires. Repeat past maxSessions.
		const results: HttpResult[] = [];
		for (let attempt = 0; attempt < 5; attempt += 1) {
			results.push(
				await call(port, initializeBody, {
					Accept: "application/json",
					"Content-Type": "application/json",
				}),
			);
