describe("bughunt: one disconnected request in a session", () => {
	it("does not destroy a sibling in-flight request in the same session", async () => {
		vi.spyOn(console, "error").mockImplementation(() => undefined);
		let release!: () => void;
		const gate = new Promise<void>((resolve) => {
			release = resolve;
		});
		let started = 0;
		const factory = () => {
			const server = new McpServer({ name: "bughunt", version: "1.0.0" });
			server.registerTool("slow", { description: "slow" }, async () => {
				started += 1;
				await gate;
				return { content: [{ type: "text", text: "done" }] };
			});
			return Promise.resolve(server);
		};
		const handle = await startStreamableHttpServer(
			{ transport: "http", host: "127.0.0.1", port: 0 },
			"fake-key",
			factory,
		);
		handles.push(handle);
		const port = serverPort(handle.server);
		const headers = {
			Accept: "application/json, text/event-stream",
			"Content-Type": "application/json",
		};
		const init = await call(port, initializeBody, headers);
		const sessionId = String(init.headers["mcp-session-id"]);
		const sessionHeaders = {
			...headers,
			"mcp-session-id": sessionId,
			"mcp-protocol-version": "2025-06-18",
		};
