			jsonrpc: "2.0",
			id,
			method: "tools/call",
			params: { name: "slow", arguments: {} },
		});

		// Request B: the one the client keeps waiting for.
		const sibling = call(port, toolCall(2), sessionHeaders).then(
			(result) => ({ ok: true as const, result }),
			(error: Error) => ({ ok: false as const, error: error.message }),
		);
		// Request A: the client gives up on it (e.g. its own timeout).
		const abandoned = request({
			host: "127.0.0.1",
			port,
			path: "/mcp",
			method: "POST",
			headers: sessionHeaders,
		});
